long sum_to(long n) {
    long acc = 0;
    while (n > 0) {              /* was: return sum_to(n - 1, acc + n); */
        acc += n--;
    }
    return acc;
}

static long step(long n, long acc) {
    if (n == 0) return acc;
    /* Clang 13+: the build fails if this cannot be a real tail call */
    __attribute__((musttail)) return step(n - 1, acc + n);
}

